// Komendy z komputera (jedna komenda = jedna linia):
//   sX – prędkość zadana [obr/min]   pX – Kp   iX – Ki   dX – Kd   ? – odczyt nastaw
// Wiadomości do komputera (format c=X):
//   v=<prędkość mierzona> s=<prędkość zadana> w=<PWM>   – cyklicznie co OKRES_WYS
//   p=<Kp> i=<Ki> d=<Kd>                                – po '?' i po zmianie nastawy

const int pinT = 5, halla = 3;

//============ przekładnia i współczynnik prędkości ============
// Enkoder (4 magnesy) siedzi na trybie 1. Przełożenie tryb 1 -> wał wyjściowy (tabela 2):
// 35/9 * 28/16 * 30/14 ≈ 14.58
const float PRZEKLADNIA = (35.0 / 9.0) * (28.0 / 16.0) * (30.0 / 14.0);
// 4 zmiany stanu = 1 obrót trybu enkodera; suma 4 czasów w ms -> obr/min wału wyjściowego
const float wsp = 60.0 * 1000.0 / PRZEKLADNIA;

//============ czasy ============
const unsigned long OKRES_REG = 20;   // ms – okres pracy regulatora (stały, bo człon I i D liczone są per krok)
const unsigned long OKRES_WYS = 100;  // ms – co ile wysyłać prędkość do komputera
const unsigned long MAX_CZAS  = 300;  // ms – brak impulsu dłużej = silnik stoi

//============ zmienne współdzielone z przerwaniem ============
volatile unsigned long pomiar = 0;
volatile int numer = 0;
volatile int pomiary[4] = {0, 0, 0, 0};

//============ regulator ============
float Kp = 3.0, Ki = 0.05, Kd = 0.05;
float V_ref = 100.0, V_out = 0.0, uchyb = 0.0, prev_u = 0.0, I = 0.0, D = 0.0;
long pwm_d = 150;

unsigned long ostReg = 0, ostWys = 0;

void setup()
{
  pinMode(pinT, OUTPUT);
  pinMode(halla, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(halla), przerwanie, CHANGE);
  Serial.begin(9600);
}

void przerwanie() {
  unsigned long czas = millis();
  pomiary[numer] = int(czas - pomiar);
  pomiar = czas;
  numer++;
  if (numer > 3) numer = 0;
}

// Gdy silnik stoi, przerwania nie przychodzą – wpisujemy 999, żeby suma > 2000 dała prędkość 0
void sprawdzPostoj() {
  noInterrupts();
  unsigned long czas = millis();
  if (czas - pomiar > MAX_CZAS) {
    pomiary[numer] = 999;
    numer++;
    if (numer > 3) numer = 0;
    pomiar = czas;
  }
  interrupts();
}

float predkoscMierzona() {
  float suma = 0;
  noInterrupts();                       // kopia tablicy bez ryzyka zmiany w trakcie odczytu
  for (int i = 0; i < 4; i++) suma += pomiary[i];
  interrupts();
  return ((suma == 0) || (suma > 2000)) ? 0 : wsp / suma;
}

void wyslijNastawy() {
  Serial.print("p="); Serial.print(Kp, 3);
  Serial.print(" i="); Serial.print(Ki, 3);
  Serial.print(" d="); Serial.println(Kd, 3);
}

void obsluzKomende() {
  if (!Serial.available()) return;
  char znak = Serial.read();
  switch (znak) {
    case 's':
    case 'S':
      V_ref = Serial.parseFloat();          // osobno, bo max() to makro i wywołałoby parseFloat dwa razy
      if (V_ref < 0) V_ref = 0;
      break;
    case 'p':
      Kp = Serial.parseFloat();
      wyslijNastawy();
      break;
    case 'i':
      Ki = Serial.parseFloat();
      wyslijNastawy();
      break;
    case 'd':
      Kd = Serial.parseFloat();
      wyslijNastawy();
      break;
    case '?':
      wyslijNastawy();
      break;
    // pozostałe znaki (np. '\r', '\n') są ignorowane
  }
}

void regulator() {
  V_out = predkoscMierzona();
  uchyb = V_ref - V_out;
  if (pwm_d < 255 && pwm_d > 0 && Ki > 0) I += uchyb;   // całkowanie tylko poza nasyceniem (anti-windup)
  D = uchyb - prev_u;
  prev_u = uchyb;
  if(I < 0) I = 0;
  pwm_d = constrain(Kp * uchyb + Ki * I + Kd * D, 0, 255);
  analogWrite(pinT, pwm_d);
}

void wyslijPredkosc() {
  Serial.print("v="); Serial.print(V_out);
  Serial.print(" s="); Serial.print(V_ref);
  Serial.print(" w="); Serial.println(pwm_d);
}

void loop() {
  sprawdzPostoj();
  obsluzKomende();

  unsigned long teraz = millis();
  if (teraz - ostReg >= OKRES_REG) {
    ostReg = teraz;
    regulator();
  }
  if (teraz - ostWys >= OKRES_WYS) {
    ostWys = teraz;
    wyslijPredkosc();
  }
}
